#!/usr/bin/env python3
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
WEB = ROOT / "src/main/resources/web"
HOSTS = (
    "index.html", "cvss-v31.html", "cisa-kev.html", "epss.html",
    "asset-context.html", "network-reachability.html", "business-impact.html",
    "assets.html", "asset-links.html",
)
CONTRACT = "RISK_METHOD_SELECTION_POLICY_ADMIN_UI_V1"
MARKER = '  <script src="/ui/rbvm-ui.js" defer></script>'

MODULE = r'''  <script>
(()=>{'use strict';
const CONTRACT='RISK_METHOD_SELECTION_POLICY_ADMIN_UI_V1';
const NO_DEFAULT='EXPLICIT_ID_AND_SHA_ONLY_NO_DEFAULT';
const POLICY_SEMANTICS='EXACT_REVISION_AND_SHA_NO_CURRENT_LATEST_OR_DEFAULT';
const rawFetch=window.fetch.bind(window);let queued=false;
document.documentElement.dataset.riskMethodPolicyUiContract=CONTRACT;
const h=(tag,attrs={},...children)=>{const node=document.createElement(tag);for(const[key,value]of Object.entries(attrs)){if(value==null||value===false)continue;if(key==='class')node.className=value;else if(key==='text')node.textContent=String(value);else if(key.startsWith('on'))node.addEventListener(key.slice(2).toLowerCase(),value);else if(key==='value')node.value=String(value);else node.setAttribute(key,String(value))}for(const child of children.flat())if(child!=null)node.append(child instanceof Node?child:document.createTextNode(String(child)));return node};
const btn=(label,fn,kind='secondary')=>h('button',{class:`button button-${kind}`,type:'button',text:label,onclick:fn});
const call=(text,kind='info')=>h('div',{class:`callout callout-${kind}`,text});
const pair=(label,value,mono=false)=>h('div',{class:'detail'},h('dt',{text:label}),h('dd',{class:mono?'mono':'',text:value??'—'}));
const title=value=>String(value||'').toLowerCase().replace(/(^|[_\s-])\w/g,part=>part.toUpperCase()).replaceAll('_',' ');
const compactSha=value=>value?`${value.slice(0,12)}…${value.slice(-8)}`:'—';
function schedule(){if(queued)return;queued=true;queueMicrotask(()=>{queued=false;enhance()})}
function enhance(){const drawer=document.querySelector('.drawer');if(!drawer)return;const body=drawer.querySelector('.drawer-body'),tabs=body?.querySelector('.tabs[role="tablist"]');if(!tabs||tabs.querySelector('[data-risk-method-policy]'))return;const tab=btn('Risk policy',()=>render(body,tab));tab.className='tab';tab.setAttribute('role','tab');tab.setAttribute('aria-selected','false');tab.dataset.riskMethodPolicy='true';tabs.append(tab)}
function activate(body,tab){const tabs=body.querySelector('.tabs[role="tablist"]');tabs.querySelectorAll('[role="tab"]').forEach(node=>node.setAttribute('aria-selected','false'));tab.setAttribute('aria-selected','true');while(tabs.nextSibling)tabs.nextSibling.remove()}
async function api(path,options={}){const response=await rawFetch(path,{...options,cache:'no-store'});let json=null;try{json=await response.clone().json()}catch(_){}if(!response.ok){const error=new Error(json?.detail||json?.title||`HTTP ${response.status}`);error.status=response.status;error.code=json?.code||'';throw error}return{response,json}}
const exactRevision=value=>/^[1-9]\d*$/.test(String(value).trim())?String(value).trim():null;
const exactSha=value=>/^[a-f0-9]{64}$/.test(String(value).trim())?String(value).trim():null;
function policyView(payload,response,context){const policy=payload?.policy||{};const status=payload?.installationStatus;const root=h('section',{class:'panel','data-policy-result':'true'},h('div',{class:'panel-header'},h('div',{},h('h2',{class:'panel-title',text:context}),h('p',{class:'panel-subtitle',text:'Immutable tenant-scoped primary risk-method policy identity'}))),h('div',{class:'panel-body'}));if(payload?.selectionSemantics!==POLICY_SEMANTICS){root.querySelector('.panel-body').append(call('Policy response does not advertise exact revision-and-SHA semantics. It is not presented as valid policy state.','warning'));return root}root.querySelector('.panel-body').append(status?h('div',{class:'inline-actions'},h('span',{class:'badge state-present',text:status==='INSERTED'?'Inserted immutable revision':'Exact revision replayed'})):null,call('This persisted revision is not a current/latest/default activation pointer. Multiple immutable revisions may coexist; activation requires a separate versioned contract.'),h('dl',{class:'details-grid'},pair('Policy revision',policy.revision),pair('Policy SHA-256',policy.policySha256,true),pair('Selection role',title(policy.selectionRole)),pair('Method family',title(policy.methodFamily)),pair('Method ID',policy.methodId,true),pair('Method version',policy.methodVersion),pair('Method SHA-256',policy.methodSha256,true),pair('Policy contract',policy.policyContractId,true),pair('Canonical format',policy.canonicalPayloadFormat,true),pair('ETag',response.headers.get('ETag')||'—',true),pair('Location',response.headers.get('Location')||'—',true)));return root}
function candidateView(candidate){return h('section',{class:'panel'},h('div',{class:'panel-body'},h('strong',{text:candidate.label}),h('dl',{class:'details-grid'},pair('Family',title(candidate.family)),pair('Method ID',candidate.id,true),pair('Version',candidate.version),pair('Method SHA-256',candidate.sha,true))))}
async function render(body,tab){activate(body,tab);body.append(call('Risk Method Selection Policy administration is tenant-scoped. It records immutable primary-method policy revisions only; this UI does not infer an active, current, latest, or default revision.'),call('Candidate catalog order is presentation-only. Formula and derived methods remain independent outputs and are never averaged or ranked here.'),h('div',{class:'skeleton','data-policy-load':'true'}));try{const[formulaCatalog,derivedCatalog]=await Promise.all([api('/api/v1/formulas'),api('/api/v1/derived-risk-methodologies')]);body.querySelector('[data-policy-load]')?.remove();if(formulaCatalog.json?.selectionSemantics!==NO_DEFAULT||derivedCatalog.json?.selectionSemantics!==NO_DEFAULT){body.append(call('One or more method catalogs do not advertise explicit no-default selection semantics. Policy administration is disabled.','warning'));return}const candidates=[];for(const formula of formulaCatalog.json?.formulas||[])candidates.push({family:'RBVM_FORMULA',id:formula.formulaId,version:formula.formulaVersion,sha:formula.formulaSha256,label:`RBVM Formula · ${formula.outputName}`});for(const methodology of derivedCatalog.json?.methodologies||[])candidates.push({family:'STANDARD_DERIVED',id:methodology.methodologyId,version:methodology.version,sha:methodology.methodologySha256,label:`${methodology.provider} · ${methodology.sourceModel}`});if(!candidates.length){body.append(call('No accepted risk methods are available in the runtime catalogs.','warning'));return}const byKey=new Map(candidates.map(candidate=>[`${candidate.family}|${candidate.id}|${candidate.version}|${candidate.sha}`,candidate]));const methodSelect=h('select',{'aria-label':'Exact risk method identity'});methodSelect.append(h('option',{value:'',text:'Select exact risk method identity…'}));for(const candidate of candidates){const key=`${candidate.family}|${candidate.id}|${candidate.version}|${candidate.sha}`;methodSelect.append(h('option',{value:key,text:`${candidate.label} · v${candidate.version} · ${compactSha(candidate.sha)}`}))}methodSelect.value='';const revision=h('input',{type:'number',min:'1',step:'1',inputmode:'numeric','aria-label':'Policy revision',placeholder:'Enter explicit revision'});revision.value='';const installStatus=h('div',{class:'status-message',role:'status','aria-live':'polite'}),installResult=h('div',{class:'stack','data-policy-install-result':'true'});const installButton=btn('Install exact policy revision',async()=>{const exact=exactRevision(revision.value),candidate=byKey.get(methodSelect.value);if(!exact||!candidate){installStatus.className='status-message error';installStatus.textContent='Enter a positive revision and explicitly select one exact method identity.';return}installButton.disabled=true;installStatus.className='status-message';installStatus.textContent='Installing or replaying the exact immutable policy revision…';try{const path=`/api/v1/risk-method-selection-policy-installations/${exact}/${candidate.family}/${encodeURIComponent(candidate.id)}/${candidate.version}/${candidate.sha}`;const result=await api(path,{method:'POST'});installStatus.textContent=result.json?.installationStatus==='REPLAYED'?'Exact immutable policy revision replayed.':'Immutable policy revision inserted.';installResult.replaceChildren(policyView(result.json,result.response,'Installed policy revision'))}catch(error){installStatus.className='status-message error';installStatus.textContent=error.status===403?'Operator role is required to install a risk-method policy revision.':error.status===409?'That revision is already bound to a different immutable policy identity. Choose a deliberate new revision; the UI will not auto-increment it.':error.status===503?'Risk Method Selection Policy persistence is unavailable in this runtime.':error.message}finally{installButton.disabled=false}},'primary');const installPanel=h('section',{class:'panel'},h('div',{class:'panel-header'},h('div',{},h('h2',{class:'panel-title',text:'Install immutable policy revision'}),h('p',{class:'panel-subtitle',text:'Revision and method identity are both explicit. No value is derived from existing revisions or catalog order.'}))),h('div',{class:'panel-body'},h('div',{class:'form-grid'},h('label',{},h('span',{text:'Policy revision'}),revision),h('label',{},h('span',{text:'Exact risk method'}),methodSelect)),installStatus,h('div',{class:'form-actions'},installButton),installResult));const readRevision=h('input',{type:'number',min:'1',step:'1',inputmode:'numeric','aria-label':'Exact policy revision to read',placeholder:'Revision'});readRevision.value='';const readSha=h('input',{type:'text',maxlength:'64',spellcheck:'false',autocomplete:'off','aria-label':'Exact policy SHA-256 to read',placeholder:'64-character lowercase SHA-256'});readSha.value='';const readStatus=h('div',{class:'status-message',role:'status','aria-live':'polite'}),readResult=h('div',{class:'stack','data-policy-read-result':'true'});const readButton=btn('Read exact policy revision',async()=>{const exact=exactRevision(readRevision.value),sha=exactSha(readSha.value);if(!exact||!sha){readStatus.className='status-message error';readStatus.textContent='Enter both an exact positive revision and its lowercase policy SHA-256.';return}readButton.disabled=true;readStatus.className='status-message';readStatus.textContent='Reading exact immutable policy identity…';try{const result=await api(`/api/v1/risk-method-selection-policies/${exact}/${sha}`);readStatus.textContent='Exact immutable policy revision loaded.';readResult.replaceChildren(policyView(result.json,result.response,'Exact policy revision'))}catch(error){readStatus.className='status-message error';readStatus.textContent=error.status===404?'No persisted policy matches that exact revision and SHA. No fallback revision is selected.':error.status===503?'Risk Method Selection Policy persistence is unavailable in this runtime.':error.message}finally{readButton.disabled=false}},'secondary');const readPanel=h('section',{class:'panel'},h('div',{class:'panel-header'},h('div',{},h('h2',{class:'panel-title',text:'Read exact policy identity'}),h('p',{class:'panel-subtitle',text:'Both immutable identifiers are required; there is no collection, max-revision, current, latest, or default lookup.'}))),h('div',{class:'panel-body'},h('div',{class:'form-grid'},h('label',{},h('span',{text:'Policy revision'}),readRevision),h('label',{},h('span',{text:'Policy SHA-256'}),readSha)),readStatus,h('div',{class:'form-actions'},readButton),readResult));const inventory=h('section',{class:'panel'},h('div',{class:'panel-header'},h('div',{},h('h2',{class:'panel-title',text:'Accepted exact method identities'}),h('p',{class:'panel-subtitle',text:'Discovery only. Order carries no precedence, preference, or default semantics.'}))),h('div',{class:'panel-body'},h('div',{class:'stack'},...candidates.map(candidateView))));body.append(installPanel,readPanel,inventory)}catch(error){body.querySelector('[data-policy-load]')?.remove();body.append(call(error.status===503?'Risk-method catalogs or persistence are unavailable in this runtime.':`Risk Method Selection Policy administration could not be loaded: ${error.message}`,'warning'))}}
new MutationObserver(schedule).observe(document.documentElement,{childList:true,subtree:true});window.addEventListener('DOMContentLoaded',schedule);
})();
  </script>
'''

host = (WEB / "index.html").read_text(encoding="utf-8")
for name in HOSTS:
    text = (WEB / name).read_text(encoding="utf-8")
    if text != host:
        raise SystemExit(f"{name}: Frontend V2 hosts are not byte-identical before patch")
if CONTRACT in host:
    raise SystemExit("risk method selection policy UI is already installed")
if host.count(MARKER) != 1:
    raise SystemExit(f"expected one shared JS marker, found {host.count(MARKER)}")
updated = host.replace(MARKER, MODULE + MARKER, 1)
for name in HOSTS:
    (WEB / name).write_text(updated, encoding="utf-8")
print("Risk Method Selection Policy Administration UI: PATCHED")
